function drawBuilding(x,type){const sx=worldX(x);if(sx<-260||sx>W+260)return;ctx.save();if(type==='car'){ctx.fillStyle='#292e29';ctx.beginPath();ctx.moveTo(sx-82,GROUND-20);ctx.lineTo(sx-68,GROUND-54);ctx.lineTo(sx-37,GROUND-66);ctx.lineTo(sx+38,GROUND-64);ctx.lineTo(sx+75,GROUND-41);ctx.lineTo(sx+93,GROUND-34);ctx.lineTo(sx+99,GROUND-15);ctx.closePath();ctx.fill();ctx.fillStyle='#69736a77';ctx.beginPath();ctx.moveTo(sx-47,GROUND-57);ctx.lineTo(sx-30,GROUND-66);ctx.lineTo(sx+8,GROUND-63);ctx.lineTo(sx+15,GROUND-47);ctx.closePath();ctx.fill();ctx.fillStyle='#121714';for(const a of [-54,57]){ctx.beginPath();ctx.arc(sx+a,GROUND-15,13,0,7);ctx.fill();ctx.strokeStyle='#687064';ctx.lineWidth=3;ctx.stroke()}line(sx-75,GROUND-24,sx+81,GROUND-31,'#64604e',2);ctx.fillStyle='#aa684d';ctx.fillRect(sx+88,GROUND-32,8,7)}else if(type==='bus'){rr(sx-100,GROUND-83,198,70,6,'#4b4d40');ctx.fillStyle='#262e2a';for(let i=0;i<5;i++)ctx.fillRect(sx-84+i*35,GROUND-74,26,22);ctx.fillStyle='#171c19';ctx.fillRect(sx-96,GROUND-25,193,10);for(const a of [-66,68]){ctx.beginPath();ctx.arc(sx+a,GROUND-15,13,0,7);ctx.fillStyle='#0f1412';ctx.fill();ctx.strokeStyle='#737467';ctx.lineWidth=3;ctx.stroke()}}else if(type==='tree'){ctx.fillStyle='#282d24';ctx.fillRect(sx-8,GROUND-145,17,146);ctx.fillStyle='#30392c';for(let i=0;i<6;i++){ctx.beginPath();ctx.moveTo(sx-70+i*11,GROUND-96-i*17);ctx.lineTo(sx+8,GROUND-236+i*13);ctx.lineTo(sx+80-i*10,GROUND-94-i*9);ctx.closePath();ctx.fill()}ctx.fillStyle='#59604755';ctx.beginPath();ctx.ellipse(sx-18,GROUND-156,48,88,-.2,0,Math.PI*2);ctx.fill()}else if(type==='cabin'){ctx.fillStyle='#38382d';ctx.fillRect(sx-60,GROUND-90,120,91);ctx.fillStyle='#252923';ctx.beginPath();ctx.moveTo(sx-77,GROUND-88);ctx.lineTo(sx,GROUND-145);ctx.lineTo(sx+78,GROUND-88);ctx.fill();ctx.fillStyle='#131918';ctx.fillRect(sx-12,GROUND-54,27,54);ctx.fillStyle='#b17a50';ctx.fillRect(sx+32,GROUND-66,17,18);line(sx-47,GROUND-90,sx+57,GROUND-90,'#746a51',4)}else if(type==='relay'){ctx.fillStyle=