function drawHuman(x,y,opts={}){const facing=opts.facing||1,walk=opts.walk||0,sx=x,sy=y;ctx.save();ctx.translate(sx,sy);ctx.scale(facing,1);const bob=Math.sin(walk)*2,step=Math.sin(walk)*7;ctx.translate(0,bob);ctx.fillStyle='rgba(0,0,0,.42)';ctx.beginPath();ctx.ellipse(0,0,22,5,0,0,7);ctx.fill();if(opts.dead){ctx.rotate(-.08);ctx.fillStyle='#594b43';ctx.fillRect(-18,-16,36,12);ctx.restore();return}
