ctx.strokeStyle=opts.hostile?'#292d29':'#303632';ctx.lineWidth=7;ctx.lineCap='round';line(-5,-23,-7+step,-5,'#333a35',7);line(6,-23,8-step,-5,'#343b36',7);rr(-14+step,-8,12,7,2,'#141a18');rr(3-step,-8,12,7,2,'#141a18');
