ctx.fillStyle='#9a806a';ctx.fillRect(-5,-57,10,7);ctx.fillStyle='#b18b6e';ctx.beginPath();ctx.ellipse(1,-64,9,11,0,0,7);ctx.fill();ctx.fillStyle='#282c28';ctx.beginPath();ctx.arc(0,-69,10,Math.PI,Math.PI*2);ctx.lineTo(10,-63);ctx.lineTo(-9,-63);ctx.fill();ctx.fillStyle='#c1a07e';ctx.fillRect(6,-65,3,2);
