function drawEnemy(e){const sx=worldX(e.x);if(sx<-90||sx>W+90)return;ctx.save();ctx.translate(sx,e.y);ctx.globalAlpha=e.dead?Math.max(.15,1-e.fade/3):1;const sway=Math.sin(frame*.08+e.phase)*3,mut=e.type==='mutant',sold=e.type==='soldier';ctx.fillStyle='rgba(0,0,0,.42)';ctx.beginPath();ctx.ellipse(0,0,mut?28:20,5,0,0,7);ctx.fill();ctx.strokeStyle=sold?'#555648':mut?'#474c3b':'#41463a';ctx.lineWidth=mut?13:9;ctx.lineCap='round';line(-6,-21,-9+sway,-5,ctx.strokeStyle,mut?14:9);line(6,-20,8-sway,-4,ctx.strokeStyle,mut?13:8);ctx.fillStyle=sold?'#45493d':mut?'#525342':'#4c5141';ctx.beginPath();ctx.moveTo(-12,-54);ctx.lineTo(-18,-38);ctx.lineTo(-12,-20);ctx.lineTo(13,-19);ctx.lineTo(17,-41);ctx.lineTo(11,-55);ctx.closePath();ctx.fill();if(mut){ctx.fillStyle='#747052';ctx.beginPath();ctx.moveTo(-15,-49);ctx.lineTo(-26,-62);ctx.lineTo(-10,-56);ctx.fill();ctx.beginPath();ctx.moveTo(12,-49);ctx.lineTo(24,-66);ctx.lineTo(17,-48);ctx.fill()}ctx.strokeStyle=sold?'#474b40':'#565a49';ctx.lineWidth=6;line(-12,-45,-22,-31,ctx.strokeStyle,6);line(12,-45,24,-33,ctx.strokeStyle,6);ctx.fillStyle='#827d63';ctx.beginPath();ctx.ellipse(1,-64,10,12,0,0,7);ctx.fill();ctx.fillStyle='#30332c';ctx.beginPath();ctx.arc(0,-68,11,Math.PI,0);ctx.fill();ctx.fillStyle='#ab5544';ctx.fillRect(-5,-65,3,2);ctx.fillRect(4,-65,3,2);if(sold){ctx.fillStyle='#222a27';ctx.fillRect(-11,-72,23,6);ctx.fillStyle='#9e986d';ctx.fillRect(-4,-71,10,3);ctx.fillStyle='#252b27';ctx.fillRect(12,-39,23,5);ctx.fillRect(31,-39,5,8)}else if(!mut){ctx.fillStyle='#7b7258';ctx.fillRect(-11,-44,23,4)}if(e.hp<(e.type==='mutant'?105:e.type==='soldier'?75:55)){ctx.fillStyle='#171b18';ctx.fillRect(-18,-88,36,3);ctx.fillStyle='#b25847';ctx.fillRect(-18,-88,36*e.hp/(e.type==='mutant'?105:e.type==='soldier'?75:55),3)}ctx.restore()}
