function handleKeyDown(event){const key=event.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown','tab'].includes(key))event.preventDefault();if(event.repeat)return;if(key==='escape'||key==='p'){pauseGame();return}if(paused||!started)return;keys[key===' '?'space':key]=true;if(key==='e')interact();else if(key==='r')reload();else if(key==='f')melee();else if(key==='1')useItem('bandage');else if(key==='2')useItem('food');else if(key==='3')useItem('water');else if(key==='tab')openPanel('inventory');else if(key==='j')openPanel('journal');else if(key==='m')openPanel('map')}
