function interact(){const i=interactables.find(a=>!a.used&&Math.abs(a.x-player.x)<a.radius );
if(!i){notify('NOTHING WITHIN REACH' );
return}
if(i.type==='relay'){if(state.step===0){i.used=true;state.step=1;state.xp+=20;updateQuest( );
notify('SIGNAL LOGGED — BLACKSITE / NORTH 09' );
showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">EMERGENCY BROADCAST · 17:42 UTC</div><h1>A VOICE IN THE STATIC</h1><div class="story-line">“...North 09. The subjects aren't dead. I repeat, they are not dead. If you can hear this, find the medic at the east treeline. The Directorate—”<br><br><span class="ending">[TRANSMISSION LOST]</span></div><p>The signal ends in a burst of static. Someone out there knows what happened here.</p><div class="modal-actions">${panelButton('CONTINUE','close')}</div>`)}
else notify('THE RELAY IS SILENT')}
else if(i.type==='cache'){i.used=true;const take=i.x<1200?['ammo']:i.x<3500?['supplies']:['meds'];if(take[0]==='ammo'){state.reserve+=12;state.bandage++;notify('FIELD PACK: +12 ROUNDS · +1 BANDAGE')}
else if(take[0]==='supplies'){state.scrap+=3;state.food++;notify('SUPPLIES FOUND: +3 SCRAP · +1 FOOD')}
else{state.meds+=2;state.water++;notify('SEALED CASE: +2 MEDS · +1 WATER')}state.xp+=10;updateHud( );
save()}
else if(i.type==='survivor'){if(state.step===1){i.used=true;state.step=2;state.meds++;state.bandage++;updateQuest( );
showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">WILLOW LINE · 17:58</div><h1>THE WANDERING MEDIC</h1><p>“Eli. I used to patch people up for the county. Now I patch whoever doesn't point a gun at me.”</p><div class="story-line">He studies the coordinates you copied from the relay. “North checkpoint. There were soldiers there before the fall. If they're still there, don't let them take you alive. The facility is real. I saw what they brought in.”</div><p>Eli gives you a field dressing and medical supplies, then turns back toward the trees.</p><div class="modal-actions">${panelButton('TAKE THE ROAD NORTH','close')}</div>` );
save()}
else if(state.step<1)notify('THE MEDIC IS WATCHING THE ROAD' );
else notify('ELI HAS MOVED ON')}
else if(i.type==='checkpoint'){if(state.step===2){showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">NORTH CHECKPOINT · 18:31</div><h1>NO SAFE PASSAGE</h1><p>Two soldiers have fortified the road. They haven't seen you yet.</p><div class="story-line">You could make a run for the broken culvert in the storm, or fight your way through. Either way, there's no going back.</div><div class="modal-actions">${panelButton('SNEAK THROUGH · -20 STAMINA','sneak')}${panelButton('FIGHT · THEY WILL REMEMBER','fight','secondary')}</div>`)}
else if(state.step<2)notify('A MILITARY BARRICADE BLOCKS THE ROAD' );
else notify('THE CHECKPOINT IS ABANDONED')}
else if(i.type==='lab'){if(state.step===3){i.used=true;state.step=4;updateQuest( );
state.xp+=20;showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">NORTH 09 · RESTRICTED ACCESS</div><h1>THE BLACKSITE</h1><div class="story-line">The door groans open. Behind it: a subterranean lab, abandoned in a hurry. The wall is covered in evacuation marks. Every name has been crossed out — except one: E. VALE.</div><p>A stairwell descends into the dark. Your radio crackles: “Mara? If you find the vault, don't let them release it. Please.” A voice you recognize from the broadcast.</p><div class="modal-actions">${panelButton('DESCEND','close')}</div>` );
save()}
else notify('SEALED — AUTHORIZATION REQUIRED')}
else if(i.type==='sample'){if(state.step===4){i.used=true;state.step=5;updateQuest( );
showEndingChoice()}
else if(state.step<4)notify('THE VAULT IS SEALED')}save( );
updateHud()}

